@router.post("/ai/completions/stream")
async def stream_ai_completion(
    payload: AICompletionPayload,
    current_user: User = Depends(get_current_user)
):
    if payload.billing_account_id != current_user.billing_account_id and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized billing account")

    context = (
        Context.builder(current_user.billing_account_id)
        .kind("account")
        .set("account_id", current_user.billing_account_id)
        .build()
    )
    is_unlimited = ldclient.get().variation("ai_unlimited_tokens", context, default=False)
    if not is_unlimited:
        raise HTTPException(status_code=402, detail="Account quota exceeded. Upgrade required.")

    return StreamingResponse(generate_model_tokens(payload.prompt), media_type="text/event-stream")
